// AssignmentHistoryProbeQuery is a parent query with one or more existence probes against
// invite_events, combined with AND. Build it with AssignmentHavingHistory or
// AssignmentNotHavingHistory and extend it with AndHaving/AndNotHaving.
type AssignmentHistoryProbeQuery struct {
	q assignment.Query
	p []assignmentHistoryProbeQueryProbe
}

type assignmentHistoryProbeQueryProbe struct {
	c   inviteevent.Query
	neg bool
}

// AssignmentHavingHistory narrows q to rows with at least one matching invite_events row —
// the filtered semi-join, in one statement. The child predicates are
// typed by the child's own package; ids and values meet only here.
func AssignmentHavingHistory(q assignment.Query, ps ...inviteevent.Pred) AssignmentHistoryProbeQuery {
	return AssignmentHistoryProbeQuery{q: q}.AndHaving(ps...)
}

// AssignmentNotHavingHistory narrows q to rows with NO matching invite_events row — the
// filtered anti-join.
//
// Read the predicates carefully: this is "has no invite_events row matching
// these", not "has a invite_events row that does not match". With no predicates
// at all it is "has none". The two questions have different answers
// whenever a parent has several children, and SQL spells them the same
// way round.
func AssignmentNotHavingHistory(q assignment.Query, ps ...inviteevent.Pred) AssignmentHistoryProbeQuery {
	return AssignmentHistoryProbeQuery{q: q}.AndNotHaving(ps...)
}

// AndHaving adds another EXISTS probe against invite_events, ANDed with the
// ones already there.
func (h AssignmentHistoryProbeQuery) AndHaving(ps ...inviteevent.Pred) AssignmentHistoryProbeQuery {
	return h.probe(false, ps...)
}

// AndNotHaving adds a NOT EXISTS probe against invite_events. This is how
// "has one of these but none of those" is one statement:
//
//	AssignmentHavingHistory(q, bought).AndNotHaving(alsoBought)
func (h AssignmentHistoryProbeQuery) AndNotHaving(ps ...inviteevent.Pred) AssignmentHistoryProbeQuery {
	return h.probe(true, ps...)
}

func (h AssignmentHistoryProbeQuery) probe(neg bool, ps ...inviteevent.Pred) AssignmentHistoryProbeQuery {
	// Copied rather than appended in place: a composer is a value, and
	// two chains branching from one base must not share a backing array.
	p := make([]assignmentHistoryProbeQueryProbe, len(h.p), len(h.p)+1)
	copy(p, h.p)
	h.p = append(p, assignmentHistoryProbeQueryProbe{c: inviteevent.New().Unordered().Where(ps...), neg: neg})
	return h
}

var assignmentHistoryProbeQueryLowering = func() runtime.Lowering {
	lw := assignment.Lowering()
	parentFrag := lw.Frag
	lw.Frag = func(op, col uint32) runtime.Frag {
		if col >= runtime.ChildColBase {
			return inviteevent.FragOf(op, col-runtime.ChildColBase)
		}
		return parentFrag(op, col)
	}
	// The token's relation id picks the header: 0 positive, 1 negated.
	// Both probes are the same relation, so only the polarity varies.
	lw.Exists = func(rel uint32) string {
		if rel == 1 {
			return "NOT EXISTS (SELECT 1 FROM \"invite_events\" AS \"_storm_e\" WHERE \"_storm_e\".\"assignment_id\" = \"assignments\".\"id\""
		}
		return "EXISTS (SELECT 1 FROM \"invite_events\" AS \"_storm_e\" WHERE \"_storm_e\".\"assignment_id\" = \"assignments\".\"id\""
	}
	return lw
}()

var assignmentHistoryProbeQueryCache = runtime.NewTreeCache()

func (h AssignmentHistoryProbeQuery) stmt(count bool) (*runtime.Stmt, []runtime.Tok) {
	var buf [44]runtime.Tok
	toks := h.q.PredToks(buf[:0])
	stack := 0
	if len(toks) > 0 {
		stack = 1
	}
	for _, pr := range h.p {
		child := pr.c.PredToks(nil)
		toks = runtime.OffsetCols(toks, child, runtime.ChildColBase)
		arity := uint32(0)
		if len(child) > 0 {
			arity = 1 // the child stream reduces to one stack entry
		}
		rel := uint32(0)
		if pr.neg {
			rel = 1
		}
		toks = append(toks, runtime.MakeExists(rel, arity))
		stack++
	}
	if stack > 1 {
		toks = append(toks, runtime.MakeGroup(runtime.KAnd, uint32(stack)))
	}
	if !count {
		toks = h.q.OrderToks(toks)
	}
	sel, cnt, limitSfx := assignment.StmtPieces()
	prefix, suffix := sel, limitSfx
	if count {
		prefix, suffix = cnt, ""
	}
	if st := assignmentHistoryProbeQueryCache.Get(toks); st != nil {
		return st, toks
	}
	return assignmentHistoryProbeQueryCache.Put(toks, runtime.SpliceTree(prefix, toks, assignmentHistoryProbeQueryLowering, suffix)), toks
}

// bind returns the arguments in STREAM order: parent predicates, then
// each probe's, then the parent's paging. Each probe takes its own
// binder — bindPreds resets the arenas it fills, so two probes sharing
// one binder would have the second silently overwrite the first.
func (h AssignmentHistoryProbeQuery) bind(pb *assignment.Binder, paging bool) ([]any, []*inviteevent.Binder) {
	args := h.q.BindPreds(pb, nil)
	cbs := make([]*inviteevent.Binder, 0, len(h.p))
	for _, pr := range h.p {
		cb := inviteevent.GetBinder()
		cbs = append(cbs, cb)
		args = pr.c.BindPreds(cb, args)
	}
	if paging {
		args = h.q.BindPaging(pb, args)
	}
	return args, cbs
}

func (h AssignmentHistoryProbeQuery) err() error {
	if err := h.q.Err(); err != nil {
		return err
	}
	for _, pr := range h.p {
		if err := pr.c.Err(); err != nil {
			return err
		}
	}
	return nil
}

// All runs the composed statement.
func (h AssignmentHistoryProbeQuery) All(ctx context.Context, ex runtime.Executor) ([]assignment.Row, error) {
	if err := h.err(); err != nil {
		return nil, err
	}
	st, _ := h.stmt(false)
	if st.Err != nil {
		return nil, st.Err
	}
	pb := assignment.GetBinder()
	defer assignment.PutBinder(pb)
	args, cbs := h.bind(pb, true)
	defer func() {
		for _, cb := range cbs {
			inviteevent.PutBinder(cb)
		}
	}()
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var sl runtime.Slab
	var out []assignment.Row
	for rows.Next() {
		out = append(out, assignment.Row{})
		if err := assignment.Scan(rows.RawValues(), &out[len(out)-1], &sl); err != nil {
			return nil, err
		}
	}
	return out, rows.Err()
}

// Count runs the composed count: no ordering, no paging.
func (h AssignmentHistoryProbeQuery) Count(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := h.err(); err != nil {
		return 0, err
	}
	st, _ := h.stmt(true)
	if st.Err != nil {
		return 0, st.Err
	}
	pb := assignment.GetBinder()
	defer assignment.PutBinder(pb)
	args, cbs := h.bind(pb, false)
	defer func() {
		for _, cb := range cbs {
			inviteevent.PutBinder(cb)
		}
	}()
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return 0, err
	}
	defer rows.Close()
	if !rows.Next() {
		return 0, rows.Err()
	}
	return runtime.Int8(rows.RawValues()[0]), rows.Err()
}

